import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Insieme quoziente","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/j_teoria-degli-insiemi/jc/jcga.md","filePath":"lezioni/j_teoria-degli-insiemi/jc/jcga.md"}`),a={name:`lezioni/j_teoria-degli-insiemi/jc/jcga.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="insieme-quoziente" tabindex="-1">Insieme quoziente <a class="header-anchor" href="#insieme-quoziente" aria-label="Permalink to “Insieme quoziente”">​</a></h1><p>La relazione di equivalenza è importantissima perché se riusciamo ad individuarla su un insieme l&#39;insieme stesso viene suddiviso in sottoinsiemi (chiamati anche classi) tali che formano una <a href="./../jb/jbh.html">partizione</a> dell&#39;insieme di partenza, cioè gli elementi di un nuovo insieme, l&#39;<strong>insieme quoziente</strong>.</p><p>Esempi:</p><p class="text-red">Considero l&#39;insieme degli alunni di un istituto scolastico e considero la relazione: [&quot;è nella stessa aula di&quot;]</p><ul><li><strong>riflessiva:</strong> ognuno è nella stessa aula di se stesso</li><li><strong>simmetrica:</strong> se Alice è nella stessa aula di Bruno anche Bruno è nella stessa aula di Alice</li><li><strong>transitiva:</strong> se Alice è nella stessa classe di Bruno e Bruno è nella stessa aula di Carla allora Alice è nella stessa aula di Carla</li></ul><p>Quindi è una relazione di <strong>equivalenza</strong>. Questa relazione divide tutti gli alunni dell&#39;istituto scolastico in gruppi (classi) che corrispondono alle classi dell&#39;istituto e l&#39;insieme quoziente ha come elementi queste classi: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi>A</mi></mrow><annotation encoding="application/x-tex">1A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">1</span><span class="mord mathnormal">A</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi>B</mi></mrow><annotation encoding="application/x-tex">1B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">1</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi>C</mi></mrow><annotation encoding="application/x-tex">1C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">1</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>A</mi></mrow><annotation encoding="application/x-tex">2A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">2</span><span class="mord mathnormal">A</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>B</mi></mrow><annotation encoding="application/x-tex">2B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span>, ...</p><hr><p class="text-red">Considero l&#39;insieme degli abitanti dell&#39;Italia e considero la relazione: [&quot;abita nello stesso comune&quot;]</p><ul><li><strong>riflessiva:</strong> ognuno abita nello stesso comune di se stesso</li><li><strong>simmetrica:</strong> se Aldo abita nello stesso comune di Beatrice anche Beatrice abita nello stesso comune di Aldo</li><li><strong>transitiva:</strong> se Antonio abita nello stesso comune di Bianca e Bianca abita nello stesso comune di Carlotta allora Antonio abita nello stesso comune di Carlotta</li></ul><p>Quindi è una relazione di <strong>equivalenza</strong>. Questa relazione divide tutti i cittadini italiani in gruppi (classi) che corrispondono alle città italiane e l&#39;insieme quoziente ha come elementi queste città: Milano, Venezia, Bologna, Napoli, Palermo, ...</p><hr><p>Matematicamente per individuare un elemento dell&#39;insieme quoziente basta considerarne un singolo componente; ad esempio negli esempi visti sopra potrei dire:</p><p>La classe dell&#39;alunno Bianchi Ermenegildo oppure La città italiana dove abita Antelami Antinisco</p><blockquote><p><strong>Nota:</strong> Matematicamente, dobbiamo considerare tutti gli elementi distinguibili fra loro e perfettamente individuati dal loro nome, mentre nella realtà c&#39;è qualche problema perché possono esservi delle persone con lo stesso nome.</p></blockquote>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};